```

3. Implement the `correctHomophones` function:

```swift
func correctHomophones(text: String) -> String {
    var result = ""
    let words = text.components(separatedBy: .whitespacesAndNewlines)

    for word in words {
        // Check if the word has been previously corrected
        if let replacement = correctedWords[word], !result.isEmpty {
            result += " \(replacement)"
            continue
        }

        // Iterate over the homophones and replace if found
        for (homophone, replacement) in homophones {
            if word.lowercased() == homophone.lowercased() {
                result += " \(replacement)"
                correctedWords[word] = replacement
                break
            }
        }

        // Add the uncorrected word to the dictionary for future reference
        correctedWords[word] = word
        result += " \(word)"
    }

    return result
}
```

