      $sortedArray,
      function ($a, $b) use ($order) {
         $ageA = $a['age'];
         $ageB = $b['age'];

         if ($ageA === $ageB) {
            return 0;
         }

         return $order * (($ageA > $ageB) - (($ageA < $ageB)));
      }
   );

   return $sortedArray;
}
