  let currentObject = object;
  for (let I = 0; I < keys.length; i++) {
    if (!currentObject[keys[i]]) {
      // If any key is missing, exit the loop as we can't traverse further
      return values;
    }

    currentObject = currentObject[keys[i]];

    // Push all the values from the current object into our result array
    if (Array.isArray(currentObject)) {
      values = values.concat(currentObject);
    } else {
      values.push(currentObject);
    }
  }

  return values;
}
```

