```javascript
function shuffleArray(arr) {
  const shuffledArr = [...arr]; // make a copy of the original array

  for (let I = 0; I < shuffledArr.length; i++) {
    const { position, randomize } = arr[i];

    if (!randomize) {
      shuffledArr[position - 1] = arr[i]; // keep the item at its specified position
      continue;
    }

    // If randomization is enabled, swap the item with another randomly chosen one
    let j = Math.floor(Math.random() * shuffledArr.length);

    while (shuffledArr[j] && arr[i].name !== shuffledArr[j].name) { // Avoid swapping with itself or already added items
      j = Math.floor(Math.random() * shuffledArr.length);
    }

    [shuffledArr[j], shuffledArr[i]] = [shuffledArr[i], shuffledArr[j]];
  }

  return shuffledArr;
}

// Example usage
const inputArr = [
  { name: 'apple', position: 1, randomize: false },
  { name: 'pineapple', position: 2, randomize: false },
  { name: 'orange', position: 3, randomize: true },
  { name: 'banana', position: 4, randomize: true },
  { name: 'grapes', position: 8, randomize: false },
  { name: 'lemon', position: 11, randomize: true },
  { name: 'jack fruit', position: 10, randomize: false },
  { name: 'dragon fruit', position: 5, randomize: false },
  { name: 'green apple', position: 9, randomize: false },
];

const outputArr = shuffleArray(inputArr);
console.log(outputArr);
