import { ToastContainer, toast } from 'react-toastify';
```

3. Create a function that will display the toast message. This function takes an object as a parameter containing the message and any additional options you want to customize the toast with. For example:

```javascript
const showToast = (message) => {
  toast(message, {
    type: 'success', // or 'error' for red color
    autoClose: 3000, // duration of the toast
    hideProgressBar: false, // show progress bar while loading
    closeOnClick: true, // close the toast on click
    pauseOnHover: true, // pause the animation while hovering over the toast
    draggable: false, // enable dragging of the toast
  });
};
```

4. Call the `showToast` function inside your component whenever you want to display a toast message:

```javascript
// Example usage
showToast('Message displayed');
```

5. Wrap your component with `ToastContainer` to display all the toast messages:

```javascript
return (
  <div>
    ... Your component here ...
    <ToastContainer />
  </div>
);
```

