    $acl = Get-Acl $folderpath
    $entries = $acl.Access | Sort-Object -Property IdentityReference
    $entries | ForEach-Object {
        $user = $_.IdentityReference
        $filemode = [IO.FileMode]::$_.FileSystemRights
